import{_ as o,l as i,o as e,c as n,v as t,p as m,x as r,d as p,i as s,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"线性与平方根冲击","description":"","frontmatter":{"title":"线性与平方根冲击","date":"2026-09-07T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/sqrt-impact.md","filePath":"quant/sqrt-impact.md","lastUpdated":1789023840000}'),h={name:"quant/sqrt-impact.md"};function E(c,a,A,B,u,_){const l=i("Mermaid");return e(),n("div",null,[a[1]||(a[1]=t('<h1 id="线性与平方根冲击" tabindex="-1">线性与平方根冲击 <a class="header-anchor" href="#线性与平方根冲击" aria-label="Permalink to &quot;线性与平方根冲击&quot;">​</a></h1><div class="epigraph"><p>经验上，组合交易对价格的冲击更接近成交量占比的平方根，而不是Kyle 单期均衡里那条过原点的直线；深度来自潜在流动性，不是来自已经挂出的那一薄层。</p><footer>—— Almgren, Thum, Hauptmann and Li, Direct Estimation of Equity Market Impact, Risk, 2005；以及 Torre 对 BARRA 市场冲击的平方根设定</footer></div><p><a href="/quant/kyle-model">Kyle 模型</a> 给出线性价格冲击：知情者的数量进入出清价，斜率 \\(\\lambda\\) 由噪声规模与价值不确定决定。执行与容量问题里，人们更常写</p> \\[\\Delta P \\propto \\sigma\\left(\\frac{|Q|}{V}\\right)^{\\delta}, \\]<p>\\(\\delta\\approx 1/2\\)，\\(V\\) 是成交量或 ADV，\\(\\sigma\\) 是波动。Torre 的 BARRA 手册把平方根冲击写成可校准的工程公式；Almgren 等人（2005）用机构订单直接估计，发现指数接近 0.6 或平方根。Toth 等人（2011）从潜在流动性与临界现象的角度解释为什么是根号而不是线性。本篇写线性与平方根何时各自适用、如何校准、以及混用时优化器会犯什么错。它描述的是成本如何随规模上升，不承诺存在一个「最优规模使策略稳赚」。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>组合要把一块目标仓位 \\(Q\\) 换成持仓，价格会走。若冲击对 \\(Q\\) 线性，边际成本恒定，容量问题是一条斜线：净期望 \\(\\mu_{\\mathrm{gross}}-\\lambda Q\\) 在某有限 \\(Q\\) 过零。若冲击是平方根，边际成本随 \\(Q^{-1/2}\\) 下降（平均成本仍升），小单很贵（相对价差主导，见 <a href="/quant/spread-cost">价差成本</a>），中等单的增量成本上升较慢，直到潜在流动性耗尽、指数律破裂。问题是：你的账户落在哪一段，以及回测外推到更大 AUM 时该用哪一条曲线。</p><p>线性来自 Kyle 的正态–线性均衡，对象是一次批量出清里的信息含量，不是一天里把母单拆成几百笔的执行。平方根来自母单（metaorder）的经验：许多笔同向成交累积的持久影响。用 Kyle \\(\\lambda\\) 去给母单定价，或用平方根去描述单笔对 BBO 的即时走阔，都是对象错配。</p><h3 id="指数-改的是容量曲线的形状" tabindex="-1">指数 \\(\\delta\\) 改的是容量曲线的形状 <a class="header-anchor" href="#指数-改的是容量曲线的形状" aria-label="Permalink to &quot;指数 $\\delta$ 改的是容量曲线的形状&quot;">​</a></h3><p>平均冲击 \\(c(Q)=kQ^{\\delta}\\)。\\(\\delta=1\\) 时总成本 \\(\\propto Q^2\\)（若 \\(c\\) 是对价格的加性冲击再乘 \\(Q\\)），最优执行与容量对 \\(k\\) 极敏感。\\(\\delta=1/2\\) 时总成本 \\(\\propto Q^{3/2}\\)，规模扩大时净 alpha 下降得比线性冲击更慢——这常让人误以为「平方根更乐观」。实际上平方根在小 \\(Q\\) 处的平均成本可以高于过原点的线性（因为还要加价差截距），在极大 \\(Q\\) 处又可能低估：簿耗尽后冲击超线性。容量结论必须画整条 \\(c(Q)\\)，而不是只报一个 \\(\\delta\\)。</p><p><span class="marginnote">Huberman 与 Stanzl（2004）证明：永久冲击必须对数量线性，否则存在价格操纵与准套利。经验平方根描述的多是含暂时成分的母单冲击，或是对「已完成母单的持久部分」的有偏拟合。把 \\(\\sqrt{Q}\\) 写成不可逆的永久冲击，会与无操纵条件冲突，见 <a href="/quant/temp-perm-impact">瞬时与永久冲击</a>。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>校准至少要分清：瞬时（成交时相对到达中点）、短暂（数分钟到数小时的恢复）、永久（母单结束后仍留下的）。Almgren 等人把临时冲击写成对交易速率的函数，永久冲击写成对总量的函数，并估计幂次。工程近似：</p> \\[\\text{临时}\\approx \\eta\\sigma\\,\\mathrm{sign}(v)\\left(\\frac{|v|}{V_{\\mathrm{bar}}}\\right)^{\\delta_t},\\qquad \\text{永久}\\approx \\gamma\\sigma\\,\\mathrm{sign}(Q)\\left(\\frac{|Q|}{\\mathrm{ADV}}\\right)^{\\delta_p}. \\]<p>常取 \\(\\delta_t\\approx 1\\) 或 \\(0.5\\)，\\(\\delta_p\\) 在理论约束下应取 1；若数据把 \\(\\delta_p\\) 拟成 0.5，应理解为有效窗口里仍含未恢复的暂时项，而不是推翻 Huberman–Stanzl。</p><p>\\(V\\) 的口径：当日已实现成交量前视；应用预测量或 ADV。\\(\\sigma\\) 用到达时的预测波动，使冲击在高波动日自动放大。按市值、价差、行业分层估计 \\(k\\)，不要全市场一个指数。母单应整段标记（同一决策、同一方向的一串子单），用子单回归会把平方根拟成更接近线性的「每笔很小」的世界。</p><h3 id="在优化器里的凸性" tabindex="-1">在优化器里的凸性 <a class="header-anchor" href="#在优化器里的凸性" aria-label="Permalink to &quot;在优化器里的凸性&quot;">​</a></h3><p>二次规划喜欢线性冲击导致的二次成本 \\(Q^\\top\\Lambda Q\\)。平方根平均成本使总成本 \\(\\propto |Q|^{3/2}\\)，对 \\(Q\\) 仍凸（在过原点、符号可分的通常写法下），可以用锥规划或分段线性逼近。危险的是「小单用价差、大单用根号」的拼接：若拼接不当，边际成本不单调，优化器会把仓位卡在折点上。更干净的是：优化层用线性或二次惩罚做换手与冲击的保守代理，执行层用平方根估计真实短fall，两者定期核对，而不是让研究 QP 直接吃非凸启发式。</p><p><span class="marginnote">Loeb（1983）已经用机构交易成本对规模作图，显示成本随规模凹性上升。平方根是这一族经验曲线的参数化，不是 2005 年才出现的新市场定律。制度变了，指数可能变，但「成本对规模凹、对 ADV 占比升」这一形状比具体 0.50 更稳健。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>线性 Kyle 机制是信息不对称下的理性出清：流量的信息含量随 \\(Q\\) 线性进入价格，深度 \\(1/\\lambda\\) 由噪声提供。平方根机制的叙事不同：可见簿很薄，更大的母单会从潜在流动性（未挂出的卖意、其他做市资本）里「挖」出增量深度；挖得越深，要价越高，但不是按已见档位线性加总。Toth 等把这写成流动性的临界状态：冲击与母单规模的平方根成正比，来自供给的幂律。Bouchaud 等人的传播函数则把单笔冲击的衰减加总成母单的有效根号。机制上，平方根是<strong>许多暂时冲击叠加上缓慢衰减</strong>的宏观表现，不必要求每一笔都服从 \\(\\sqrt{q}\\)。</p><p>因此：单笔吃档更接近簿的几何（可能超线性，一旦打穿数档）；母单的持久影响更常看到根号；Kyle 线性更接近「这一股流量的信息被立刻写入」的永久部分。三层可以同时存在。执行算法若按单笔平方根控速，可能过慢（把信息优势耗在时间上）或过快（在薄簿上打穿）。应对齐你要付的是哪一层。</p><h3 id="与价差截距的合成" tabindex="-1">与价差截距的合成 <a class="header-anchor" href="#与价差截距的合成" aria-label="Permalink to &quot;与价差截距的合成&quot;">​</a></h3><p>完整单位成本常写成 \\(s/2+k(Q/\\mathrm{ADV})^{\\delta}\\)。\\(\\delta\\lt 1\\) 时，存在一个规模使两项同量级；小于该规模，降换手主要靠少付价差（降频、加带宽）；大于该规模，容量受冲击斜率限制。因子衰减慢、换手低的策略往往活在价差段；统计套利日频活在两段之间；大规模指数调整活在冲击段。用单一 \\(\\delta\\) 去给三类策略做容量，会得到同一条好看但错位的曲线。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>幂律在 \\(Q/\\mathrm{ADV}\\) 的中间段最稳，两端失效：极小单被最小报价单位与半价差主导；极大单改变交易机制（谈判、大宗、停牌）。拥挤时同类母单同向，\\(V\\) 分母被高估（ADV 含了拥挤流），冲击高于平静期校准。2007 年 8 月不是把 \\(\\delta\\) 从 0.5 改成 0.7 能概括的，而是流动性供给撤了。</p><p>不要把回归 \\(\\Delta p=\\lambda Q+\\varepsilon\\) 的 \\(\\lambda\\) 叫做「已估计的 Kyle 深度」又拿去当平方根的 \\(k\\)。不要在 <a href="/quant/almgren-chriss">Almgren–Chriss</a> 的线性临时冲击闭式解里直接把项换成 \\(\\sqrt{v}\\) 还沿用双曲正弦轨迹——那是另一个变分问题。不要用全样本拟合 \\(\\delta\\) 再声称容量。应预留一段执行数据做样本外短fall 核对，并按波动分位分层。</p><p>A 股涨跌停使冲击在板上变成「无穷」：不是 \\(\\delta\\) 变大，而是约束 \\(Q\\) 不可执行。平方根公式在这些日子不应外推，应把可成交集合当成硬约束。</p><p><span class="marginnote">同一 \\(\\delta\\) 在买卖两侧可以不同：跌停附近卖出、停牌再开的买入，供给弹性不对称。校准应分方向，至少检查买入母单与卖出母单的短fall 曲线是否能共用一套 \\(k\\)。</span></p>',29)),(e(),m(d,null,{default:r(()=>[s(l,{id:"mermaid-81",class:"mermaid",graph:"flowchart%20TD%0A%20%20Q%5B%22%E6%AF%8D%E5%8D%95%E6%95%B0%E9%87%8F%20Q%22%5D%20--%3E%20LIN%5B%22%E7%BA%BF%E6%80%A7%3A%20Kyle%20%CE%BBQ%22%5D%0A%20%20Q%20--%3E%20SQR%5B%22%E5%B9%B3%E6%96%B9%E6%A0%B9%3A%20k%20%CF%83%20(Q%2FV)%5E%CE%B4%22%5D%0A%20%20LIN%20--%3E%20PERM%5B%22%E6%9B%B4%E6%8E%A5%E8%BF%91%E6%B0%B8%E4%B9%85%20%2F%20%E4%BF%A1%E6%81%AF%E5%86%99%E5%85%A5%22%5D%0A%20%20SQR%20--%3E%20META%5B%22%E6%9B%B4%E6%8E%A5%E8%BF%91%E6%AF%8D%E5%8D%95%E7%BB%8F%E9%AA%8C%E5%86%B2%E5%87%BB%22%5D%0A%20%20SPR%5B%22%E5%8D%8A%E4%BB%B7%E5%B7%AE%E6%88%AA%E8%B7%9D%22%5D%20--%3E%20TOT%5B%22%E5%8D%95%E4%BD%8D%E6%88%90%E6%9C%AC%22%5D%0A%20%20LIN%20--%3E%20TOT%0A%20%20SQR%20--%3E%20TOT%0A%20%20TOT%20--%3E%20CAP%5B%22%CE%BC_net%20%E9%9A%8F%20AUM%20%E4%B8%8B%E9%99%8D%22%5D%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[p(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=t('<h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kyle 线性冲击描述信息批量出清；平方根冲击是母单执行的经验律（Torre；Almgren et al., 2005；Toth et al., 2011）。</li><li>永久冲击在无操纵条件下应线性（Huberman–Stanzl）；经验根号多混有未恢复的暂时成分。</li><li>容量曲线的形状由 \\(\\delta\\) 与价差截距共同决定，不能只报一个指数。</li><li>优化层宜用凸代理，执行层用平方根估短fall；不要把闭式线性 AC 轨迹套到 \\(\\sqrt{v}\\) 上。</li><li>两端与涨跌停、拥挤使幂律破裂，ADV 分母在拥挤时会给出过低冲击。</li><li>出处：Almgren, Thum, Hauptmann and Li, <em>Direct Estimation of Equity Market Impact</em>, Risk, 2005；Torre, BARRA <em>Market Impact Model</em>；Kyle, <em>Econometrica</em>, 1985；Huberman and Stanzl, <em>Econometrica</em>, 2004；Toth et al., <em>Physical Review X</em>, 2011。</li></ul>',2))])}const Q=o(h,[["render",E]]);export{f as __pageData,Q as default};
